verify:
def skill():
    t = Symbol('t')
    v = (t - 1)**2*(t - 6)
    roots = [r for r in solve(v, t) if r > 0]
    ch = [r for r in roots if v.subs(t, r - Rational(1, 100))*v.subs(t, r + Rational(1, 100)) < 0]
    return diff(v, t).subs(t, ch[0])

def standard():
    t = Symbol('t')
    v = expand((t - 1)**2*(t - 6))
    a = diff(v, t)
    pts = sorted(set(real_roots(Poly(v, t))))
    vals = [v.subs(t, p) for p in [Rational(1, 2), Rational(3), Rational(7)]]
    assert [x < 0 for x in vals] == [True, True, False]
    return a.subs(t, 6)

def unique():
    return [standard()]
